"""Pure learning transitions. Messages are generated by the provider, never scripts."""
import copy
import time
import uuid
from .dialogue import camera_alerts, exercise_from_reply
from .tasks import current_node
from .courses import COURSES, DIALOGUE_VERSION, course_for, focus_for

AI_ACTIONS = {'open','hint','answer','continue','skip'}
ACTION_LABELS = {'hint':'给我一点提示','answer':'请给我完整示范','continue':'继续聊这个课题','skip':'换个例子试试'}
ACTION_LABELS_EN = {'hint':'Give me a small hint','answer':'Show me a full example','continue':'Keep exploring this topic','skip':'Try another example'}


def ensure_dialogue(s):
    """Non-destructive lazy upgrade: retain legacy messages, records and current exercise."""
    if s.get('dialogue_version')==DIALOGUE_VERSION: return s
    n=current_node(s)
    index=min(2, [0,1,1,1,2,2][min(s.get('node_index',0),5)])
    s['focus_id']=COURSES[s['task_id']]['objectives'][index]['id']
    s['exercise']=({'prompt':n['prompt']+('\n'+n['code'] if n['code'] else ''),
        'reference':n['answer'],'rubric':n['rubric'],'id':s['question_key']} if n['kind']=='question' else None)
    s['dialogue_version']=DIALOGUE_VERSION
    s['learner_state']={};s['dialogue_turn']=0;s['pending_event']=None
    return s


def message(s, role, text, source='ai', code=''):
    s['messages'].append(dict(id=str(uuid.uuid4()),role=role,text=text,code=code,source=source,
        node_id=s['focus_id'],created_at=time.time()))


def new_session(task_id, consent, language='zh-CN'):
    now=time.time();focus=COURSES[task_id]['objectives'][0]['id']
    return dict(id=str(uuid.uuid4()),task_id=task_id,language=language,content_version=DIALOGUE_VERSION,dialogue_version=DIALOGUE_VERSION,version=0,
        status='active',support_mode='on' if consent.support else 'off',consent=consent.model_dump(),
        consent_log=[dict(at=now,**consent.model_dump())],created_at=now,updated_at=now,
        node_index=0,focus_id=focus,exercise=None,question_key=str(uuid.uuid4()),
        hint_level=0,exposed=False,ready=False,messages=[],records=[],pending=None,pending_event=None,requests={},
        protected=False,episode=None,episodes_count=0,last_support_at=None,same_error_count=0,last_misconception='',
        dismissed_questions=[],prompted_evidence_keys=[],correction='',learner_state={},dialogue_turn=0,
        support_round={'turn':0,'states':[],'attempts':{}})


def public_session(s):
    s=ensure_dialogue(copy.deepcopy(s));focus=focus_for(s)
    fields=('id','task_id','content_version','dialogue_version','version','status','support_mode','consent','created_at','updated_at',
        'messages','records','hint_level','ready','exposed','protected','episode')
    # Displayed invitations are retained until an explicit user action, including legacy ones.
    if s['episode']:
        # Internal evidence, refresh signatures and attempts are not part of the browser contract.
        s['episode']={k:v for k,v in s['episode'].items() if k in ('id','question_key','reason','kind','title','created_at','expires_at','text')}
        if s['episode'].get('text'):s['episode']['expires_at']=None
    return {k:s[k] for k in fields} | {
        'node_index':course_for(s)['objectives'].index(focus), 'current_node':{
            'id':s['question_key'],'title':focus['title'],'kind':'question','prompt':'','code':''},
        'language':s.get('language','zh-CN'),'camera_alerts':camera_alerts(s),'pending':bool(s['pending']),'title':s.get('custom_title') or course_for(s)['title'],'title_version':s.get('title_version',0),'total_steps':len(course_for(s)['objectives'])}


def clear_unshown_episode(s):
    if s.get('episode'):
        if not s['episode'].get('text'):s['episode']=None
        else:s['episode'].pop('pending_context',None)


def cancel_pending(s):
    s['pending']=None;s['pending_event']=None;s['episode']=None


def reset_errors(s):
    s['same_error_count']=0;s['last_misconception']=''


def apply_control(s, command):
    ensure_dialogue(s);action=command.action
    if s['status']=='ended': return
    cancel_pending(s)
    if action=='end':
        s['status']='ended';s['support_mode']='off';s['consent']['camera']=False
    elif action=='pause':
        s['support_mode']='paused' if s['consent']['support'] else 'off';s['consent']['camera']=False;reset_errors(s)
    elif action=='resume':
        s['support_mode']='on' if s['consent']['support'] else 'off';reset_errors(s)
    elif action=='consent':
        if command.consent is None: raise ValueError('缺少同意设置。')
        s['consent']=command.consent.model_dump()
        if not s['consent']['support']: s['consent']['camera']=False
        s['support_mode']='on' if s['consent']['support'] else 'off'
        s['consent_log'].append(dict(at=time.time(),**s['consent']));reset_errors(s)
    elif action=='think': s['protected']=True
    elif action=='reject': s['dismissed_questions'].append(s['question_key'])
    elif action=='correct':
        if not command.text.strip(): raise ValueError('请写下希望纠正的内容。')
        s['correction']=command.text.strip();s['protected']=True;s['learner_state']={};reset_errors(s)
        message(s,'user',command.text.strip(),'correction')
    elif action in AI_ACTIONS:
        raise ValueError('教学动作需要由 AI 对话接口生成。')


def commit_dialogue(s, assessment, reply, state, event, text, record_user=True):
    """Only called after version/ownership/cancellation checks have passed."""
    old_focus=s['focus_id'];exercise=s.get('exercise');ev=assessment.evaluation
    if event=='message' and record_user: message(s,'user',text,'submitted')
    elif event in ACTION_LABELS:
        labels=ACTION_LABELS_EN if s.get('language')=='en' else ACTION_LABELS
        message(s,'user',labels[event],'command')
    if event=='message' and exercise:
        if ev.verdict=='supported' and not any(r.get('exercise_id')==exercise['id'] for r in s['records']):
            s['records'].append(dict(node_id=old_focus,exercise_id=exercise['id'],hints=s['hint_level'],
                status='reviewed_after_example' if s['exposed'] else 'completed_with_hint' if s['hint_level'] else 'completed_independently'))
        if ev.verdict=='incorrect' and ev.misconception:
            s['same_error_count']=s['same_error_count']+1 if s['last_misconception']==ev.misconception else 1
            s['last_misconception']=ev.misconception
        else: reset_errors(s)  # Unknown/ambiguous interrupts a consecutive error sequence too.
    if event=='skip' and exercise:
        s['records'].append(dict(node_id=old_focus,exercise_id=exercise['id'],status='skipped',hints=s['hint_level']))
    if event=='hint' or reply.assistance=='hint': s['hint_level']=min(2,s['hint_level']+1)
    if event=='answer' or reply.assistance=='answer': s['exposed']=True
    message(s,'assistant',reply.reply,'ai')
    s['focus_id']=reply.focus_id
    if reply.exercise_action=='replace':
        s['exercise']=exercise_from_reply(reply,str(uuid.uuid4()))
        s['question_key']=s['exercise']['id'];s['hint_level']=0;s['exposed']=False
        s['ready']=False;s['protected']=False
    elif reply.exercise_action=='clear':
        s['exercise']=None;s['question_key']=str(uuid.uuid4());s['hint_level']=0;s['exposed']=False;s['ready']=False
    else: s['ready']=ev.verdict=='supported' and not s['exposed']
    if old_focus!=reply.focus_id: reset_errors(s)
    s['protected']=assessment.intent=='thinking' or event=='correct'
    s['learner_state']=state;s['dialogue_turn']+=1
    s.setdefault('assessment_log',[]).append({'at':time.time(),'turn':s['dialogue_turn'],'event':event,
        'evaluation':ev.model_dump(),'state':state,'move':reply.move})
    s['pending']=None;s['pending_event']=None
    if event=='message':clear_unshown_episode(s)
    else:s['episode']=None
